command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="ce51aa2804902990776071293990dad48a4ed1f1"
$candidate="caa4e950fd9e59ff14ef0c8f36c3d6697f57d2ea"
$branch="work/search-content-regex-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UIA GUI successor fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UIA GUI successor"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "content regex candidate moved before UIA GUI successor"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-content-regex-uia-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "UIA GUI successor worktree add failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "UIA GUI successor diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "UIA GUI successor FAST failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "UIA GUI successor Release build failed"}

  & python -X utf8 tools\winui\run_checks.py gui --area search-content-regex --configuration Release
  if($LASTEXITCODE -ne 0){throw "UIA-only content regex GUI failed"}

  Write-Host "CONTENT_REGEX_UIA_FAST=PASS"
  Write-Host "CONTENT_REGEX_RELEASE_BUILD=PASS"
  Write-Host "CONTENT_REGEX_UIA_GUI=PASS"
  Write-Host "CONTENT_REGEX_PRIOR_RELEASE_NATIVE_RUN=37547329626"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
